function btn(text,fn,iconName='',cls=''){const b=node('button',cls);b.type='button';if(iconName)b.insertAdjacentHTML('afterbegin',icon(iconName));b.append(node('span','',text));b.onclick=()=>Promise.resolve(fn?.()).catch(report);return b;}
function updateWebsiteLinks(){const hide=isNative()||globalThis.abunasserDesktop?.isDesktop===true||!!nativeTVInfo();for(const id of ['gate-website-home','app-website-home']){const el=$(id);if(!el)continue;el.hidden=hide;el.setAttribute('aria-label',x('العودة للصفحة الرئيسية','Back to website'));const span=el.querySelector('span');if(span)span.textContent=x('الرئيسية','Website');else el.textContent=x('الرئيسية','Website');}}
async function syncDesktopNotifications(){const bridge=globalThis.abunasserDesktop;if(typeof bridge?.getNotificationsEnabled!=='function')return;try{const native=await bridge.getNotificationsEnabled();if(native?.ok){const wanted=state.settings.notifications===true||native.enabled===true;const result=wanted&&!native.enabled?await bridge.setNotificationsEnabled(true):native;state.settings.notifications=result?.enabled===true;}}catch{}}
