function sheet(title,content){$('sheet-title').textContent=title;$('sheet-body').replaceChildren();if(typeof content==='string')$('sheet-body').append(node('p','',content));else if(content)$('sheet-body').append(content);if(!$('sheet').open)$('sheet').showModal();paintIcons($('sheet'));triggerGlitch($('sheet'));return $('sheet-body');}
