function fieldsForm(title,fields,{submit=x('حفظ','Save'),description=''}={}){return new Promise(resolve=>{const form=node('form');if(description)form.append(node('p','',description));const inputs={};for(const f of fields){const l=node('label','',f.label),input=node(f.options?'select':f.multiline?'textarea':'input');input.name=f.name;input.type=f.type||'text';input.value=f.value??'';input.required=f.required??true;if(f.inputmode)input.inputMode=f.inputmode;if(f.placeholder)input.placeholder=f.placeholder;if(f.options){for(const o of f.options){const op=node('option','',typeof o==='string'?o:o.label);op.value=typeof o==='string'?o:o.value;input.append(op);}input.value=f.value??'';}inputs[f.name]=input;l.append(input);form.append(l);}const save=btn(submit,null,'check','primary');save.type='submit';form.append(actions(save,btn(x('إلغاء','Cancel'),closeSheet)));sheet(title,form);let done=false;const finish=value=>{if(done)return;done=true;$('sheet').removeEventListener('close',cancel);resolve(value);};const cancel=()=>finish(null);$('sheet').addEventListener('close',cancel);form.onsubmit=e=>{e.preventDefault();const values=Object.fromEntries(Object.entries(inputs).map(([key,input])=>[key,input.value]));finish(values);closeSheet();};setTimeout(()=>Object.values(inputs)[0]?.focus(),50);});}
function choices(title,rows,onChoose){const list=node('div','choice-list');for(const row of rows){const v=typeof row==='string'?{label:row,value:row}:row;const b=btn(v.label,()=>{closeSheet();return onChoose(v.value??v.label);},v.icon||'');if(v.detail)b.append(node('small','choice-value',v.detail));if(v.selected)b.classList.add('selected');list.append(b);}sheet(title,list);}
