function scope(){return Core.accountScope?.(state.account)||`${state.account?.mode||'demo'}|${state.account?.server||''}|${state.account?.username||''}`;}
function collection(){const id=scope()+'|'+state.profile;return state.collections[id]??=( {favorites:[],hidden:[],watchlist:[],history:[],progress:{},order:[],saved:{}} );}
function key(item){return Core.stableKey(scope(),item);}
function inSet(name,item){return collection()[name].includes(key(item));}
async function persist(){const data={accounts:state.accounts,profile:state.profile,profiles:state.profiles,settings:state.settings,collections:state.collections,pin:state.pin,lastChannel:state.lastChannel,account:$('remember-account').checked&&!state.demo?state.account:null,userInfo:state.userInfo};if(state.settings.privacy_mode)data.lastChannel=null;await vault.set('ui',data);}
