function contact(title=x('برمجة ابوناصر','Developed by Abunasser'),support=false){const box=node('div');box.append(node('p','',support?x('للاشتراك أو الدعم الفني، تواصل مع ابوناصر.','Contact Abunasser for subscription or support.'):x(`ابوناصر TV · برمجة وتطوير ابوناصر · الإصدار ${APP_VERSION}`,`abbeedo TV · Developed by Abunasser · Version ${APP_VERSION}`)),node('p','phone-number','0571514382'));box.append(actions(btn(x('نسخ الرقم','Copy number'),()=>copyText('0571514382'),'copy'),btn(x('مراسلة واتساب','Message on WhatsApp'),()=>openExternal(Core.BRAND.whatsapp),'chat','primary')));if(support)box.append(btn(x('إرسال تقرير تشخيص بدون بيانات الاشتراك','Send a report without subscription details'),()=>{const summary=`${brandName(state.settings.language)} ${APP_VERSION}\n${isNative()?'iPhone app':'Web'}\n${navigator.onLine?'Online':'Offline'}\n${JSON.stringify({timings:state.timings,errors:state.errorLog.slice(0,5)})}`;openExternal(Core.BRAND.whatsapp+'?text='+encodeURIComponent(summary));},'support'));sheet(title,box);}
async function copyText(value){try{if(isNative())await nativeRequest('copy',{text:value});else if(navigator.clipboard?.writeText)await navigator.clipboard.writeText(value);else{const input=node('textarea');input.value=value;document.body.append(input);input.select();if(!document.execCommand('copy'))throw Error('clipboard');input.remove();}toast(x('تم النسخ','Copied'));}catch{const box=node('div');const input=node('input');input.value=value;input.readOnly=true;input.dir='ltr';box.append(node('p','',x('اضغط مطولًا على النص ثم انسخ.','Hold the text and copy.')),input);sheet(x('نسخ','Copy'),box);input.select();}}
function openExternal(value){const u=Core.safeURL(value,location.href);if(!u)throw Error(x('الرابط غير صالح','Invalid link'));if(isNative())nativeRequest('openURL',{url:u.href}).catch(()=>{location.href=u.href;});else window.open(u.href,'_blank','noopener,noreferrer');}
function sourceMode(){const mode=$('source-mode').value,credentials=['provider','xtream'].includes(mode);$('credentials-row').hidden=!credentials;$('username').required=credentials&&mode!=='stalker';$('password').required=credentials&&mode!=='stalker';$('server').hidden=!['xtream','stalker'].includes(mode);$('playlist-url').hidden=!['m3u','direct','auto'].includes(mode);$('mac').hidden=mode!=='stalker';$('file-button').hidden=mode!=='m3u';for(const id of ['server','playlist-url','mac'])$(id).disabled=$(id).hidden;$('username').disabled=!credentials;$('password').disabled=!credentials;$('login-error').hidden=true;}
async function doLogin(account,{remember=$('remember-account').checked}={}){loadAbort?.abort();loadAbort=new AbortController();$('login-button').disabled=true;$('login-button').textContent=x('جارٍ التحقق…','Checking…');$('login-error').hidden=true;try{const started=performance.now();const auth=await api.authenticate(account,{signal:loadAbort.signal});await closePlayer();state.account={...account};state.userInfo=auth?.userInfo||auth?.user_info||{};state.demo=false;state.catalogs={};if(remember){const id=Core.accountScope(account);const existing=state.accounts.findIndex(a=>Core.accountScope(a)===id);const saved={...account,name:account.name||account.username||x('اشتراك','Subscription')};if(existing>=0)state.accounts[existing]=saved;else state.accounts.push(saved);}state.timings.login={ms:Math.round(performance.now()-started),state:'ready'};$('password').value='';state.profile=state.profiles[0]||'Default';state.lastChannel=collection().lastChannel||null;applyPreferences();await persist();showPage('home');setupDownloads();runStartScreen();}catch(error){$('login-error').textContent=report(error);$('login-error').hidden=false;}finally{$('login-button').disabled=false;$('login-button').textContent=x('دخول','Sign in');}}
function accountFromForm(){const mode=$('source-mode').value;if(mode==='auto')return detectAccountURL($('playlist-url').value.trim());const account={mode,server:mode==='provider'?Core.PROVIDER:['xtream','stalker'].includes(mode)?$('server').value.trim():'',username:['provider','xtream'].includes(mode)?$('username').value.trim():'',password:['provider','xtream'].includes(mode)?$('password').value:'',url:['m3u','direct'].includes(mode)?$('playlist-url').value.trim():'',mac:mode==='stalker'?$('mac').value.trim():''};if(['provider','xtream'].includes(mode)&&(!account.username||!account.password))throw Error(x('أدخل اسم المستخدم وكلمة المرور.','Enter your username and password.'));if(['xtream','stalker'].includes(mode)&&!Core.safeURL(account.server))throw Error(x('أدخل عنوان سيرفر صحيحًا يبدأ بـ HTTP أو HTTPS.','Enter a valid HTTP or HTTPS server address.'));if(['m3u','direct'].includes(mode)&&!Core.safeURL(account.url))throw Error(x('أدخل رابطًا صالحًا أو اختر ملف M3U.','Enter a valid URL or choose an M3U file.'));return account;}
function demoItems(){const fixture=new URL('/watch-demo.mp4',globalThis.ABUNASSER_CONFIG?.apiOrigin||location.href).href,result={live:[],movie:[],series:[]};const channels=[[x('قناة التجربة الأولى','First demo channel'),x('رياضة','Sports')],[x('أخبار التجربة','Demo news'),x('أخبار','News')],[x('عالم الأطفال · تجربة','Kids world · Demo'),x('أطفال','Kids')],[x('أفلام التجربة','Demo movies'),x('أفلام','Movies')],[x('وثائقيات التجربة','Demo documentaries'),x('وثائقي','Documentary')]];channels.forEach(([name,group],i)=>result.live.push({id:'live:demo'+i,kind:'live',name,group,url:fixture+'?channel='+i,logo:'',demo:true}));const names=x(['رحلة الضوء','وقت الحكاية','نافذة على العالم','لحظات هادئة','دروب جديدة','حكاية مكان'],['A journey of light','Story time','A window on the world','Quiet moments','New paths','A place to remember']);for(let n=0;n<6;n++)result.movie.push({id:'movie:demo'+n,kind:'movie',name:names[n]+x(' · تجربة',' · Demo'),group:n%2?x('وثائقي','Documentary'):x('مقاطع مملوكة','Owned clips'),url:fixture,year:'2026',rating:'',plot:x('مقطع اختبار مملوك لعرض الواجهة وأدوات التشغيل؛ ليس فيلمًا من اشتراك حقيقي.','An owned test clip showing the interface and playback controls; sample content without a real subscription.'),demo:true});for(let n=0;n<3;n++)result.series.push({id:'series:demo'+n,kind:'series',name:x(['حكايات التجربة','عالم الواجهة','خطوات المشاهدة'],['Demo stories','Interface world','Watching steps'])[n],group:x('مسلسلات تجريبية','Demo series'),year:'2026',plot:x('مسلسل توضيحي باستخدام مقاطع اختبار مملوكة.','Sample series using owned test clips.'),demo:true});return result;}

function demo(){state.account={mode:'demo',username:'demo',server:''};state.userInfo={};state.demo=true;state.catalogs=demoItems();state.group='';state.family='all';state.view='all';applyPreferences();showPage('home');setupDownloads();closeSheet();}
const HOME_TOOLS=[['refresh','تحديث','Refresh','refresh'],['notifications','التنبيهات','Notifications','notifications'],['account','حسابي','My account','account'],['accounts','الحسابات','Accounts','accounts'],['downloads','التنزيلات','Downloads','download'],['favorites','المفضلة','Favorites','heart'],['watchlist','أريد مشاهدته','Watchlist','bookmark'],['continue','متابعة المشاهدة','Continue watching','history'],['last','آخر قناة','Last channel','live'],['recent','المضاف حديثًا','Recently added','calendar'],['recommend','مقترحات محلية','Local suggestions','star'],['epg','دليل البرامج','Program guide','calendar']];
function renderHome(){const cards=$('home-cards');cards.replaceChildren();let order=String(state.settings.home_order||'series,live,movie').split(',');if(order.length!==3||new Set(order).size!==3||order.some(k=>!NAMES[k]))order=['series','live','movie'];for(const kind of order){const b=btn(label(kind),()=>kind==='live'?openLive():openCatalog(kind),kind,'home-card');b.dataset.kind=kind;cards.append(b);}$('home-tools').replaceChildren(...HOME_TOOLS.map(([id,ar,en,ic])=>{const b=btn(x(ar,en),()=>homeAction(id),ic);b.dataset.action=id;return b;}));const expiry=Core.formatExpiry(state.userInfo,{locale:state.settings.language==='en'?'en-GB':'ar-SA-u-ca-gregory'});$('subscription-expiry').textContent=state.demo?x('تجربة دون اشتراك · بيانات توضيحية فقط','Demo without subscription · sample data only'):expiry.known?x(`تاريخ انتهاء الاشتراك: ${expiry.date} · المتبقي: ${expiry.days} يوم`,`Subscription ends: ${expiry.date} · ${expiry.days} days left`):x('تاريخ انتهاء الاشتراك: لم يحدده المصدر','Subscription expiry: not supplied by the provider');applyPreferences();}
async function homeAction(action){if(action==='refresh'){if(state.demo){toast(x('بيانات التجربة جاهزة','Demo data is ready'));return;}delete state.catalogs[state.kind];await openCatalog(state.kind,{force:true});}else if(action==='notifications')await showNotifications();else if(action==='account')showAccount();else if(action==='accounts')showAccounts();else if(action==='downloads')showDownloads();else if(action==='last'){if(state.lastChannel)await playItem(state.lastChannel);else toast(x('لا توجد قناة سابقة بعد','No previous channel yet'));}else if(action==='epg')showGuide();else await showSavedCollection(action);}
async function getCatalog(kind,{force=false,onBatch}={}){if(state.catalogs[kind]&&!force){onBatch?.(state.catalogs[kind],{cached:true});return state.catalogs[kind];}if(state.demo)return state.catalogs[kind]||[];if(state.account?.mode==='m3u-file'){return state.catalogs[kind]||[];}const started=performance.now();const rows=await api.catalog(state.account,kind,{force,signal:loadAbort?.signal,onBatch:(items,meta)=>{if(!state.timings[kind]?.first)state.timings[kind]={first:Math.round(performance.now()-started),rows:items.length,state:'partial'};onBatch?.(items,meta);}});state.catalogs[kind]=Array.isArray(rows)?rows:rows.items||[];state.timings[kind]={...state.timings[kind],total:Math.round(performance.now()-started),rows:state.catalogs[kind].length,state:'ready'};return state.catalogs[kind];}
async function openCatalog(kind,{force=false,view='all'}={}){if(!state.account)return showPage('login');loadAbort?.abort();loadAbort=new AbortController();const generation=++state.generation;state.kind=kind;state.view=view;state.group='';state.family='all';state.query='';state.filters={};state.limit=60;$('catalog-search').value='';showPage('catalog');state.settings.last_section=kind;saveSoon();state.loading=true;$('catalog-status').textContent=x('جارٍ جلب المحتوى… يمكنك الرجوع في أي وقت.','Fetching content… you can go back at any time.');renderCatalog();try{const rows=await getCatalog(kind,{force,onBatch:items=>{if(state.generation!==generation||state.page!=='catalog')return;state.catalogs[kind]=items;renderCatalog();$('catalog-status').textContent=x('المحتوى الذي وصل متاح الآن؛ جارٍ إكمال القائمة…','Received content is ready; fetching the rest…');}});if(state.generation!==generation||state.page!=='catalog')return;state.catalogs[kind]=rows;$('catalog-status').textContent='';renderCatalog();}catch(error){if(error.name==='AbortError'||state.generation!==generation)return;$('catalog-status').textContent=report(error);}finally{if(state.generation===generation)state.loading=false;}}
function filtered(rows=state.catalogs[state.kind]||[],options={}){const c=collection();return Core.filterItems(rows,{scope:scope(),kind:state.kind,group:state.group,family:state.kind==='live'?state.family:'',query:state.query,...state.filters,parental:state.settings.parental_enabled,hidden:c.hidden,favorites:c.favorites,watchlist:c.watchlist,history:c.history,favoritesOnly:state.view==='favorites'||state.family==='favorites',watchlistOnly:state.view==='watchlist',historyOnly:state.view==='continue'||state.family==='history',recentOnly:state.view==='recent',dedupeMovies:state.settings.dedupe_movies,dedupeChannels:state.settings.deduplicate_channels,sort:state.sort,order:c.order,...options});}
function categoryButtons(rows,{receiver=false}={}){rows=rows.filter(item=>!collection().hidden.includes(key(item))&&(!state.settings.parental_enabled||!Core.isAdult(item)));const box=node('div');const counts=new Map();for(const item of rows){if(state.settings.parental_enabled&&Core.isAdult(item)||collection().hidden.includes(key(item)))continue;counts.set(item.group||x('غير مصنف','Uncategorized'),(counts.get(item.group||x('غير مصنف','Uncategorized'))||0)+1);}const choose=(family,group)=>{state.family=family;state.group=group;state.limit=60;receiver?renderReceiver():renderCatalog();};if((state.kind==='live'||receiver)&&state.settings.auto_categories){for(const family of Core.LIVE_FAMILIES){const count=family.id==='all'?rows.length:family.id==='favorites'?rows.filter(i=>inSet('favorites',i)).length:family.id==='history'?rows.filter(i=>collection().history.some(h=>h.key===key(i))).length:rows.filter(i=>Core.classifyLive(i)===family.id).length;if(!count&&!['all','favorites','history'].includes(family.id))continue;const b=btn(`${String([...box.children].length+1).padStart(3,'0')}  ${x(family.ar,family.en)} (${count})`,()=>choose(family.id,''));b.classList.toggle('selected',state.family===family.id&&!state.group);b.dataset.family=family.id;box.append(b);}}else{const b=btn(x(`كل ${label(state.kind)} (${rows.length})`,`All ${label(state.kind)} (${rows.length})`),()=>choose('all',''));b.classList.toggle('selected',!state.group);box.append(b);}for(const [group,count]of counts){const b=btn(`${group} (${count})`,()=>choose('all',group));b.classList.toggle('selected',state.group===group);box.append(b);}return [...box.children];}
function renderCatalog(){if(state.page!=='catalog')return;$('catalog-tabs').replaceChildren(...['live','movie','series'].map(kind=>{const b=btn(label(kind),()=>kind==='live'?openLive():openCatalog(kind));b.classList.toggle('selected',kind===state.kind);return b;}));$('catalog-filters').hidden=state.kind==='live';$('catalog-favorites').classList.toggle('selected',state.view==='favorites');const source=state.catalogs[state.kind]||[];$('category-list').replaceChildren(...categoryButtons(source));let rows=filtered(source);if(state.view==='recommend'){const groups=new Set(collection().history.map(h=>h.item?.group).filter(Boolean));rows=[...rows].sort((a,b)=>Number(groups.has(b.group))-Number(groups.has(a.group))||Number(b.rating||0)-Number(a.rating||0));}$('collection-title').textContent=state.group||label(state.kind);$('catalog-count').textContent=String(rows.length);$('catalog-grid').classList.toggle('live-grid',state.kind==='live');$('catalog-grid').replaceChildren(...rows.slice(0,state.limit).map((item,index)=>mediaCard(item,index)));$('catalog-empty').hidden=rows.length>0||state.loading;$('catalog-more').hidden=rows.length<=state.limit;}
function posterImage(item,className=''){const url=Core.safeURL(item.logo||item.cover||item.poster,location.href);if(url){const img=node('img',className);img.src=url.href;img.alt='';img.loading='lazy';img.referrerPolicy='no-referrer';img.onerror=()=>{img.replaceWith(fallbackPoster(item));};return img;}return fallbackPoster(item);}
