function flattenEpisodes(value){if(!value)return[];const rows=[];if(Array.isArray(value)){for(const ep of value)rows.push({...ep,kind:'episode',name:ep.name||ep.title});}else for(const [season,episodes]of Object.entries(value))for(const ep of Array.isArray(episodes)?episodes:[]){rows.push({...ep,season,kind:'episode',providerId:String(ep.providerId||ep.id||''),id:String(ep.id||'').startsWith('episode:')?String(ep.id):'episode:'+ep.id,name:ep.name||ep.title||x('حلقة','Episode')});}return rows.sort((a,b)=>Number(a.season||1)-Number(b.season||1)||Number(a.episode_num||a.episode||0)-Number(b.episode_num||b.episode||0));}
