function decodeText(value){const text=String(value||'');if(!text||text.length%4||!/[A-Za-z0-9+/]+=*$/.test(text))return text;try{const decoded=new TextDecoder().decode(Uint8Array.from(atob(text),c=>c.charCodeAt(0)));return /[\p{L}\p{N}]/u.test(decoded)&&!decoded.includes('\ufffd')?decoded:text;}catch{return text;}}
