async function addReminder(channel,program,time){state.reminders??=[];state.reminders.push({channel:channel.name,title:decodeText(program.title||program.name),time});await vault.set('reminders',state.reminders);scheduleReminders();toast(x('تم ضبط التذكير أثناء استخدام التطبيق. للتنبيهات خارج التطبيق استخدم أذونات الآيفون المدعومة.','Reminder set while the app is active. Outside the app, iPhone notification support and permission apply.'));}
function scheduleReminders(){for(const reminder of state.reminders||[]){if(reminder.scheduled||reminder.time<Date.now())continue;const delay=reminder.time-Date.now();if(delay>2147483000)continue;reminder.scheduled=true;setTimeout(async()=>{toast(reminder.channel+' · '+reminder.title);if(state.settings.notifications)await deliverNotification({id:reminder.channel+'|'+reminder.title+'|'+reminder.time,title:reminder.channel,body:reminder.title,url:location.origin+'/app'});},delay);}}

async function showNotifications(){const box=node('div');box.append(node('p','',x('تنبيهات التطبيق والتذكيرات المحلية المتاحة على جهازك.','App announcements and local reminders available on your device.')));try{const base=globalThis.ABUNASSER_CONFIG?.apiOrigin||location.origin;const response=await appFetch(new URL('/api/announcements',base),{cache:'no-store'});if(response.ok){const data=await response.json();for(const message of data.messages||[]){box.append(node('h3','',message.title),node('p','',message.body));}if(!data.messages?.length)box.append(node('p','',x('لا توجد تنبيهات حاليًا.','There are no announcements right now.')));}else throw Error('Announcements unavailable');}catch{box.append(node('p','',x('تعذر جلب التنبيهات الآن.','Could not fetch announcements right now.')));}box.append(btn(x('أذونات الإشعارات','Notification permissions'),requestNotifications,'notifications'));sheet(x('التنبيهات','Notifications'),box);}
