async function managePIN(){if(state.pin){const check=await fieldsForm(x('التحقق من الرمز الحالي','Verify current PIN'),[{name:'pin',label:x('رمز PIN الحالي','Current PIN'),type:'password',inputmode:'numeric'}]);if(!check)return;if(!await Core.verifyPIN(check.pin,state.pin))throw Error(x('الرمز غير صحيح.','Incorrect PIN.'));choices(x('قفل التطبيق','App lock'),[{value:'change',label:x('تغيير الرمز','Change PIN')},{value:'remove',label:x('إزالة القفل','Remove lock')}],async value=>{if(value==='remove'){state.pin=null;await persist();renderSettings();}else await setPIN();});}else await setPIN();}
async function setPIN(){const values=await fieldsForm(x('رمز PIN جديد','New PIN'),[{name:'pin',label:x('من 4 إلى 8 أرقام','4 to 8 digits'),type:'password',inputmode:'numeric'},{name:'confirm',label:x('تأكيد الرمز','Confirm PIN'),type:'password',inputmode:'numeric'}]);if(!values)return;if(!/^\d{4,8}$/.test(values.pin)||values.pin!==values.confirm)throw Error(x('أدخل رمزًا من 4 إلى 8 أرقام وطابق التأكيد.','Use matching 4 to 8 digit PINs.'));state.pin=await Core.derivePIN(values.pin);await persist();renderSettings();toast(x('تم حفظ القفل','App lock saved'));}
async function parentalControls(){if(state.pin){const values=await fieldsForm(x('الرقابة الأبوية','Parental controls'),[{name:'pin',label:x('رمز PIN','PIN'),type:'password',inputmode:'numeric'}]);if(!values)return;if(!await Core.verifyPIN(values.pin,state.pin))throw Error(x('الرمز غير صحيح.','Incorrect PIN.'));}else{const box=node('div');box.append(node('p','',x('ننصح بتعيين رمز PIN لحماية تغيير الرقابة الأبوية.','Set a PIN to protect parental control changes.')),actions(btn(x('تعيين رمز','Set PIN'),()=>setPIN(),'pin'),btn(x('تفعيل الحجب الآن','Enable blocking'),async()=>{state.settings.parental_enabled=true;await persist();closeSheet();renderSettings();},'parental')));return sheet(x('الرقابة الأبوية','Parental controls'),box);}state.settings.parental_enabled=!state.settings.parental_enabled;await persist();renderSettings();toast(state.settings.parental_enabled?x('تم تفعيل حجب تصنيفات الكبار','Adult category blocking enabled'):x('تم إيقاف الحجب','Blocking disabled'));}
function hiddenContent(){const c=collection(),known=allKnown(),box=node('div');if(!c.hidden.length)box.append(node('p','',x('لا يوجد محتوى مخفي.','No content is hidden.')));for(const id of c.hidden){const row=node('div','list-row');row.append(node('div','',known.get(id)?.name||x('عنصر محفوظ','Saved item')),btn(x('إظهار','Unhide'),async()=>{c.hidden=c.hidden.filter(v=>v!==id);await persist();hiddenContent();},'eye'));box.append(row);}sheet(x('المحتوى المخفي','Hidden content'),box);}
async function exportBackup(){const values=await fieldsForm(x('نسخة احتياطية مشفرة','Encrypted backup'),[{name:'password',label:x('كلمة مرور قوية للنسخة','Strong backup password'),type:'password'},{name:'confirm',label:x('تأكيد كلمة المرور','Confirm password'),type:'password'}],{description:x('تتضمن النسخة الاشتراكات المحفوظة والتفضيلات. احتفظ بكلمة المرور؛ لا يمكن استعادة النسخة دونها.','The backup contains saved subscriptions and preferences. Keep its password; it cannot be recovered without it.')});if(!values)return;if(values.password.length<8||values.password!==values.confirm)throw Error(x('استخدم كلمة مرور متطابقة من 8 أحرف على الأقل.','Use matching passwords of at least 8 characters.'));await persist();const text=await vault.exportBackup(values.password);saveBlob(new Blob([text],{type:'application/json'}),'Abunasser-TV-encrypted-backup.json');}
