function appFetch(url,options={}){return isNative()&&Native.nativeFetch?Native.nativeFetch(String(url),options):fetch(url,options);}
function detectAccountURL(value){const url=Core.safeURL(value);if(!url)throw Error(x('أدخل رابط اشتراك صالحًا.','Enter a valid subscription link.'));const username=url.searchParams.get('username'),password=url.searchParams.get('password');if(username&&password){const server=new URL(url);server.pathname=server.pathname.replace(/\/(?:get|player_api)\.php\/?$/i,'');server.search='';server.hash='';return{mode:'xtream',server:server.href.replace(/\/$/,''),username,password};}return{mode:/\.m3u(?:$|\?)/i.test(url.pathname+url.search)||/\/(?:get|playlist)\.php$/i.test(url.pathname)?'m3u':'direct',url:url.href,server:'',username:'',password:''};}
let qrScript=null,scanScript=null,cameraStream=null,cameraFrame=0,refreshTick=0;
function loadLocalScript(path,globalName){if(globalThis[globalName])return Promise.resolve(globalThis[globalName]);return new Promise((resolve,reject)=>{const script=node('script');script.src=path;script.onload=()=>globalThis[globalName]?resolve(globalThis[globalName]):reject(Error(x('تعذر فتح أداة QR.','Could not load QR tools.')));script.onerror=()=>reject(Error(x('تعذر تحميل أداة QR.','Could not load QR tools.')));document.head.append(script);});}
async function qrPicture(url){qrScript??=loadLocalScript('/qrcode.js','qrcode').catch(error=>{qrScript=null;throw error;});const generate=await qrScript;const qr=generate(0,'M');qr.addData(url);qr.make();const wrapper=node('div','qr-picture');wrapper.innerHTML=qr.createSvgTag({cellSize:4,margin:4,scalable:true});wrapper.setAttribute('aria-label',x('رمز الربط المشفر','Encrypted pairing code'));return wrapper;}
