async function createPairing(){
 if(pairSession?.active)return showPairing();await pairSession?.destroy?.().catch(()=>{});
 pairSession=new PairingClient();const status=node('p','muted',x('جارٍ إنشاء جلسة الربط…','Creating a pairing session…'));sheet(x('ربط هذا الجهاز','Pair this device'),status);
 try{const invitation=await pairSession.create({deviceName:brandName(state.settings.language)+(isNative()?' · iPhone':' · Web')});state.pairStatus='waiting';
  pairSession.startReceiving({onAccount:async account=>{await doLogin(account,{remember:$('remember-account').checked});if(!state.account)throw Error(x('لم ينجح التحقق من الاشتراك.','Subscription validation failed.'));state.pairStatus='received';closeSheet();toast(x('تم استقبال الاشتراك والتحقق منه','Subscription received and validated'));},onStatus:value=>{state.pairStatus=value.status;const label=$('pair-status');if(label)label.textContent=value.status==='received'?x('تم الربط. يمكنك استخدام الريموت من الجهاز الآخر.','Connected. The other device can now control playback.'):x('في انتظار بيانات الاشتراك من الجهاز الآخر…','Waiting for subscription details from the other device…');},onError:report,onCommand:applyRemoteCommand,getState:()=>({currentTitle:state.current?.name||'',...playerSnapshot(),isPlaying:!!controller?.getState?.().playing,remoteActions:['up','down','left','right','ok','back','home','play_pause','volume_down','volume_up','previous_channel','next_channel','seek','search']})});await showPairing(invitation);
 }catch(error){await pairSession?.close().catch(()=>{});pairSession=null;throw error;}
}
async function showPairing(invitation={url:pairSession?.url,expiresAt:pairSession?.expiresAt}){if(!pairSession?.active)return createPairing();const box=node('div');box.append(node('p','',x('امسح الرمز بالجهاز الآخر وأدخل بيانات اشتراكك هناك. لا تشارك الرمز علنًا.','Scan this code with your other device and enter the subscription there. Do not publish this code.')));box.append(await qrPicture(invitation.url));const status=node('p','muted',state.pairStatus==='received'?x('تم الربط','Connected'):x('في انتظار الجهاز الآخر…','Waiting for the other device…'));status.id='pair-status';box.append(status,node('p','',x('تنتهي الجلسة خلال 20 دقيقة. يمكنك إنهاؤها الآن من الزر أدناه.','The session expires within 20 minutes. You can end it using the button below.')),actions(btn(x('نسخ رابط الربط','Copy pairing link'),()=>copyText(invitation.url),'copy'),btn(x('إنهاء الربط','End pairing'),async()=>{await pairSession?.close();pairSession=null;closeSheet();},'close','danger')));sheet(x('ربط هذا الجهاز','Pair this device'),box);}
function remoteDevices(){if(pairSession?.active)return showPairing();const box=node('div');box.append(node('p','',x('اربط متصفحًا أو جوالًا آخر مؤقتًا لاستخدامه ريموتًا لهذا الجهاز. لا تُعرض بيانات اشتراكك في حالة الريموت.','Temporarily pair another browser or phone as a remote for this device. Remote state never displays your subscription credentials.')),btn(x('بدء الربط','Start pairing'),createPairing,'qr','primary'));sheet(x('الأجهزة والريموت','Devices and remote'),box);}
async function handleScannedQR(value){const url=Core.safeURL(String(value||'').trim());if(!url)throw Error(x('رمز QR لا يحتوي رابطًا صالحًا.','The QR code does not contain a valid link.'));const trusted=new URL(globalThis.ABUNASSER_CONFIG?.apiOrigin||(/^https?:/.test(location.protocol)?location.origin:'https://www.abbeedo.com')).origin;if(url.origin!==trusted||url.pathname!=='/pair.html'||!url.hash)throw Error(x('هذا ليس رمز ربط ابوناصر لهذا الموقع.','This is not an Abunasser pairing code for this site.'));stopCamera();closeSheet();openExternal(url.href);}
function stopCamera(){cancelAnimationFrame(cameraFrame);cameraFrame=0;for(const track of cameraStream?.getTracks()||[])track.stop();cameraStream=null;}
async function decodeQRImage(file){if(!file)return;if(file.size>15*1024*1024)throw Error(x('الصورة أكبر من 15 ميغابايت.','Image exceeds 15 MB.'));scanScript??=loadLocalScript('jsqr.js','jsQR').catch(error=>{scanScript=null;throw error;});const decode=await scanScript;const bitmap=await createImageBitmap(file);try{const canvas=node('canvas'),ratio=Math.min(1,1600/Math.max(bitmap.width,bitmap.height));canvas.width=Math.round(bitmap.width*ratio);canvas.height=Math.round(bitmap.height*ratio);const ctx=canvas.getContext('2d',{willReadFrequently:true});ctx.drawImage(bitmap,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height),code=decode(pixels.data,pixels.width,pixels.height);if(!code)throw Error(x('لم يُعثر على رمز QR واضح في الصورة.','No readable QR code was found in the image.'));await handleScannedQR(code.data);}finally{bitmap.close();}}
async function scanQR(){if(isNative()){const value=await nativeRequest('scanQR',{});return handleScannedQR(value?.value||value?.text||value);}if(!navigator.mediaDevices?.getUserMedia)return sheet(x('كاميرا QR','QR camera'),x('الكاميرا غير متاحة هنا. استخدم صورة الرمز أو الصق رابط الربط.','The camera is unavailable here. Choose a QR image or paste the pairing link.'));stopCamera();scanScript??=loadLocalScript('jsqr.js','jsQR').catch(error=>{scanScript=null;throw error;});const decode=await scanScript;const video=node('video','qr-camera');video.playsInline=true;video.muted=true;const box=node('div');box.append(node('p','',x('وجّه الكاميرا نحو رمز الربط.','Point the camera at the pairing code.')),video,btn(x('إيقاف الكاميرا','Stop camera'),()=>{stopCamera();closeSheet();},'close'));sheet(x('مسح رمز QR','Scan QR'),box);try{cameraStream=await navigator.mediaDevices.getUserMedia({video:{facingMode:'environment'},audio:false});video.srcObject=cameraStream;await video.play();const canvas=node('canvas'),ctx=canvas.getContext('2d',{willReadFrequently:true});let last=0;const frame=now=>{if(!cameraStream||!$('sheet').open)return stopCamera();if(video.videoWidth&&now-last>300){last=now;const ratio=Math.min(1,800/video.videoWidth);canvas.width=Math.round(video.videoWidth*ratio);canvas.height=Math.round(video.videoHeight*ratio);ctx.drawImage(video,0,0,canvas.width,canvas.height);const pixels=ctx.getImageData(0,0,canvas.width,canvas.height),code=decode(pixels.data,pixels.width,pixels.height);if(code){stopCamera();handleScannedQR(code.data).catch(report);return;}}cameraFrame=requestAnimationFrame(frame);};cameraFrame=requestAnimationFrame(frame);}catch(error){stopCamera();throw error;}}
async function importPlaylist(file){if(!file)return;if(file.size>64*1024*1024)throw Error(x('القائمة أكبر من 64 ميغابايت.','Playlist exceeds 64 MB.'));const items=Core.parseM3U(await file.text(),globalThis.ABUNASSER_CONFIG?.apiOrigin||location.href);await doLogin({mode:'m3u-file',name:file.name,items},{remember:$('remember-account').checked});if(state.account?.mode==='m3u-file'){state.catalogs=Object.fromEntries(['live','movie','series'].map(kind=>[kind,items.filter(item=>item.kind===kind)]));await persist();renderHome();}}
async function pickPlaylist(){if(isNative()){const value=await nativeRequest('importFile',{types:['public.m3u-playlist','public.text']});const text=value?.text??value?.contents;if(typeof text==='string')return importPlaylist(new File([text],value.name||'playlist.m3u',{type:'text/plain'}));}else $('m3u-file').click();}
function goBack(){if($('sheet').open){closeSheet();return;}if(!$('player-page').hidden){if(!$('receiver-panel').hidden){$('receiver-panel').hidden=true;return;}closePlayer().catch(report);return;}if(state.page==='details'){showPage('catalog');renderCatalog();return;}if(state.page==='settings'){showPage(state.account?'home':'login');return;}showPage(state.account?'home':'login');}
function moveFocus(direction){const active=document.activeElement;if(/INPUT|TEXTAREA|SELECT/.test(active?.tagName))return false;const container=$('sheet').open?$('sheet'):!$('receiver-panel').hidden?$('receiver-panel'):!$('player-page').hidden?$('player-page'):document.querySelector('.page:not([hidden])');const current=active?.getBoundingClientRect();let candidates=[...container.querySelectorAll('button,a,input,select')].filter(el=>!el.disabled&&el.getClientRects().length&&!el.closest('[hidden]'));const rowOnly=['left','right'].includes(direction)&&active?.classList.contains('home-card');if(rowOnly)candidates=candidates.filter(el=>el.classList.contains('home-card'));if(!candidates.length)return false;if(!current||!container.contains(active)){candidates[0].focus();return true;}const cx=current.x+current.width/2,cy=current.y+current.height/2;let best=null,bestScore=Infinity;for(const candidate of candidates){if(candidate===active)continue;const r=candidate.getBoundingClientRect(),dx=r.x+r.width/2-cx,dy=r.y+r.height/2-cy;if(direction==='left'&&dx>=-4||direction==='right'&&dx<=4||direction==='up'&&dy>=-4||direction==='down'&&dy<=4)continue;const primary=['left','right'].includes(direction)?Math.abs(dx):Math.abs(dy),secondary=['left','right'].includes(direction)?Math.abs(dy):Math.abs(dx),score=primary+secondary*2.5;if(score<bestScore){best=candidate;bestScore=score;}}if(best){best.focus();best.scrollIntoView({block:'nearest',inline:'nearest'});return true;}return rowOnly;}
async function applyRemoteCommand(command){if(!$('screen-lock').hidden)return;const value=command?.value;if(['up','down','left','right'].includes(command.action))return moveFocus(command.action);switch(command.action){case'ok':if(!$('player-page').hidden&&state.current?.kind==='live'&&($('receiver-panel').hidden||!$('receiver-panel').contains(document.activeElement)))toggleReceiver();else document.activeElement?.click?.();break;case'back':goBack();break;case'home':await closePlayer();showPage(state.account?'home':'login');break;case'play_pause':if(controller?.getState?.().playing)await controller.pause();else await controller?.resume?.();break;case'previous_channel':await changeChannel(-1);break;case'next_channel':await changeChannel(1);break;case'volume_up':$('video').volume=Math.min(1,$('video').volume+.1);break;case'volume_down':$('video').volume=Math.max(0,$('video').volume-.1);break;case'seek':if(state.current?.kind!=='live')await controller?.seek?.(Math.max(0,Number(value?.positionMs??value)||0)/1000);break;case'search':if(!$('receiver-panel').hidden){$('receiver-search').value=String(value?.query??value??'').slice(0,300);renderReceiver();}else if(state.page==='catalog'){$('catalog-search').value=String(value?.query??value??'').slice(0,300);state.query=$('catalog-search').value;renderCatalog();}break;}}
function runStartScreen(){const start=state.settings.start_screen;if(start==='last_channel'&&state.lastChannel){playItem(state.lastChannel).catch(report);return;}if(start==='last_section'&&['live','movie','series'].includes(state.settings.last_section)){state.settings.last_section==='live'?openLive():openCatalog(state.settings.last_section);return;}if(['live','movie','series'].includes(start)){start==='live'?openLive():openCatalog(start);}}
function localActivity(){lastActive=Date.now();$('screensaver').hidden=true;}
function tickIdle(){const now=Date.now();if(state.settings.screensaver_mode!=='off'&&now-lastActive>Number(state.settings.screensaver_minutes||5)*60000&&$('player-page').hidden&&!$('sheet').open&&$('screen-lock').hidden){$('screensaver').hidden=false;$('screensaver').querySelector('time').hidden=state.settings.screensaver_mode==='black';$('screensaver').querySelector('time').textContent=new Date().toLocaleTimeString(state.settings.language==='en'?'en':'ar-SA',{hour:'2-digit',minute:'2-digit'});}const hours=Number(state.settings.catalog_refresh_hours)||0;if(hours>0&&state.account&&!state.demo&&document.visibilityState==='visible'&&now-(state.lastRefresh||now)>hours*3600000&&!state.loading){state.lastRefresh=now;api.memory?.clear();state.catalogs={};if(state.page==='catalog')openCatalog(state.kind,{force:true}).catch(report);}}
