 $('unlock-form').onsubmit=async event=>{event.preventDefault();try{if(await Core.verifyPIN($('unlock-pin').value,state.pin)){$('screen-lock').hidden=true;$('unlock-pin').value='';$('unlock-error').textContent='';localActivity();if(state.startAfterUnlock){state.startAfterUnlock=false;runStartScreen();}}else $('unlock-error').textContent=x('الرمز غير صحيح','Incorrect PIN');}catch(error){$('unlock-error').textContent=report(error);}};
