async function advancedFilters(){if(state.kind==='live')return;const rows=state.catalogs[state.kind]||[],unique=field=>[...new Set(rows.map(item=>String(item[field]||'').trim()).filter(Boolean))].sort();const options=(items,title)=>[{value:'',label:title},...items.slice(0,150).map(value=>({value,label:value}))];const values=await fieldsForm(x('فلاتر الأفلام والمسلسلات','Movie and series filters'),[{name:'year',label:x('سنة الإصدار','Release year'),value:state.filters.year||'',options:options(unique('year'),x('كل السنوات','All years')),required:false},{name:'genre',label:x('النوع','Genre'),value:state.filters.genre||'',options:options(unique('genre'),x('كل الأنواع','All genres')),required:false},{name:'language',label:x('اللغة','Language'),value:state.filters.language||'',options:options(unique('language'),x('كل اللغات','All languages')),required:false},{name:'ratingFloor',label:x('أقل تقييم','Minimum rating'),value:String(state.filters.ratingFloor||''),options:[{value:'',label:x('كل التقييمات','Any rating')},...[5,6,7,8,9].map(value=>({value:String(value),label:`${value}+`}))],required:false}],{description:x('تستخدم الفلاتر بيانات المزود المتاحة ولا تفترض معلومات لم يوفرها.','Filters use available provider metadata and do not invent missing information.')});if(values){state.filters={...values,ratingFloor:Number(values.ratingFloor)||0};state.limit=60;renderCatalog();}}
async function boot(){
 bindActions();sourceMode();paintIcons();
 try{const data=await vault.get('ui',null);if(data&&typeof data==='object'){state.accounts=Array.isArray(data.accounts)?data.accounts.filter(a=>a&&typeof a==='object').slice(0,100):[];state.profiles=Array.isArray(data.profiles)&&data.profiles.length?data.profiles.filter(value=>typeof value==='string'&&value.length<100).slice(0,50):['Default'];state.profile=state.profiles.includes(data.profile)?data.profile:state.profiles[0]||'Default';state.settings={...Core.DEFAULT_SETTINGS,...(data.settings||{})};state.collections=data.collections&&typeof data.collections==='object'?data.collections:{};state.pin=data.pin||null;state.lastChannel=data.lastChannel||null;state.account=data.account&&typeof data.account==='object'?data.account:null;state.userInfo=data.userInfo||{};if(state.account?.mode==='m3u-file')state.catalogs=Object.fromEntries(['live','movie','series'].map(kind=>[kind,(state.account.items||[]).filter(item=>item.kind===kind)]));}state.reminders=await vault.get('reminders',[]);state.localEpg=await vault.get('epg',[]);}catch(error){report(error);}
 state.settings=mergeVaultPreferences(state.settings,readPreferences());await syncDesktopNotifications();state.lastRefresh=Date.now();applyPreferences();showPage(state.account?'home':'login',{remember:false});if(state.pin)$('screen-lock').hidden=false;if(state.account){await setupDownloads();if(state.pin)state.startAfterUnlock=true;else runStartScreen();}scheduleReminders();idleTick=setInterval(tickIdle,1000);
 if(!isNative()&&'serviceWorker'in navigator)navigator.serviceWorker.register('/sw.js').catch(()=>{});
 bindDesktopUpdates(desktopUpdatePanel);updateWebsiteLinks();updateMonitor=createUpdateMonitor({check:()=>checkForUpdates({fetcher:appFetch}),onUpdate:async update=>{const message=x(`يتوفر تحديث ${update.latestVersion}. افتح الإعدادات ثم تحديث التطبيق.`,`Update ${update.latestVersion} is available. Open Settings, then App update.`);toast(message);if(state.settings.notifications&&!globalThis.abunasserDesktop?.nativeUpdates)await deliverNotification({id:'release-'+update.latestVersion,title:brandName(state.settings.language),body:message,url:location.origin+'/app'});}});updateMonitor.start();announcementMonitor=createAnnouncementMonitor({fetcher:appFetch,endpoint:new URL('/api/announcements',globalThis.ABUNASSER_CONFIG?.apiOrigin||location.origin).href,isEnabled:()=>true,shouldDeliver:()=>state.settings.notifications===true&&!globalThis.abunasserDesktop?.nativeAnnouncements,onMessage:message=>toast([message.title,message.body].filter(Boolean).join(' · '))});void announcementMonitor.start();
 document.documentElement.dataset.appReady='true';
}
window.addEventListener('abunasser:native',event=>{const data=event.detail||{};if(data.type==='stopped'&&data.userDismissed&&!$('player-page').hidden&&(!(data.itemId||data.id)||(data.itemId||data.id)===state.current?.id))closePlayer().catch(report);});
export const appReady=boot().catch(error=>{report(error);document.documentElement.dataset.appReady='true';});
